import pytest


def pick(xs: list[int], seed: int) -> int:
    """Return an element of the non-empty list xs chosen deterministically
    from seed, without using randomness.

    The same xs and seed always give the same element, and the result is
    always a member of xs. Any integer seed is accepted, including negative
    values and values larger than len(xs). Raises ValueError if xs is empty.
    """
    if not xs:
        raise ValueError("xs must be non-empty")
    return xs[seed % len(xs)]


def test_returns_member() -> None:
    xs = [10, 20, 30, 40]
    for seed in range(-10, 20):
        assert pick(xs, seed) in xs


def test_deterministic() -> None:
    xs = [5, 6, 7, 8, 9]
    for seed in range(-10, 20):
        assert pick(xs, seed) == pick(xs, seed)


def test_single_element() -> None:
    for seed in (-100, -1, 0, 1, 7, 10**18):
        assert pick([42], seed) == 42


def test_negative_seed() -> None:
    xs = [1, 2, 3]
    assert pick(xs, -1) in xs
    assert pick(xs, -(10**30)) in xs


def test_large_seed() -> None:
    xs = [1, 2, 3]
    assert pick(xs, 10**30) in xs
    assert pick(xs, 2**100 + 1) in xs


def test_duplicates() -> None:
    assert pick([7, 7, 7], 5) == 7


def test_does_not_mutate() -> None:
    xs = [3, 1, 2]
    pick(xs, 4)
    assert xs == [3, 1, 2]


def test_empty_raises() -> None:
    with pytest.raises(ValueError):
        pick([], 0)


def test_seeds_cover_all_elements() -> None:
    xs = [10, 20, 30, 40, 50]
    picked = {pick(xs, seed) for seed in range(1000)}
    assert picked == set(xs)


def test_varies_with_seed() -> None:
    xs = list(range(100))
    picked = {pick(xs, seed) for seed in range(100)}
    assert len(picked) > 1

